const req=$('[A2] Validar entrada').first().json;
if($input.all().some(x=>Object.keys(x.json).length && (!x.json.id || !x.json.fields || !x.json.createdTime))) throw Error('Respuesta de consultas mal formada');
const now=Date.now();
const rows=$input.all().map(x=>x.json).filter(x=>x.id && x.fields && x.fields.Name && x.createdTime);
const own=rows.filter(r=>String(r.fields.Name).startsWith(req.persona+'_'));
const duplicate=rows.some(r=>r.fields.Name===req.evento);
const minute=own.filter(r=>now-Date.parse(r.createdTime)<60000).length;
const estado=!duplicate && minute<5 && own.length<40 && rows.length<100?'ok':'cupo';
const motivo=duplicate?'duplicado':own.length>=40?'diario':minute>=5?'minuto':rows.length>=100?'global':'';
return [{json:{estado,motivo}}];

const v=JSON.parse(String($json.output).trim().replace(/^\x60\x60\x60(?:json)?\s*|\x60\x60\x60$/g,''));const allowed=['consulta','seguimiento_reclamo','reclamo','reserva_sum','pago_expensas','derivar'];let i=allowed.includes(v.intencion)?v.intencion:'derivar';if(i==='pago_expensas')i='derivar';const re=/^\d{4}-\d\d-\d\dT\d\d:\d\d$/;let respuesta=String(v.respuesta||'Tu consulta requiere revisión de Administración.').slice(0,500);if(i==='reserva_sum'&&(!re.test(v.inicio||'')||!re.test(v.fin||''))){i='consulta';respuesta='Necesito fecha, hora de inicio y hora de fin para consultar la disponibilidad.';}let intento=0;if($runIndex>0){const x=$('[S5] Pedir corrección').all(0,$runIndex-1);intento=Number(x[x.length-1].json.intento||0)}const a=$('[A2] Validar entrada').first().json;
const detalle=String($('[B5] Usar transcripción').first().json.texto||'');
const normal=detalle.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const peligro=/\b(?:gas\b|humo|fuego|incendi|llamas?\b|chispa|cable|electrocut|cortocircuit|inund|atrapad|encerrad|intrus|forzad|derrumb|explo|tablero|electric|enchufe|disyuntor|medidor|ascensor|caid|herid|sangr|desmay)/.test(normal);
const critico_corregido=v.critico===true&&!peligro;
const critico=v.critico===true&&!critico_corregido;
const prioridad=critico_corregido?'alta':(['baja','media','alta','critica'].includes(v.prioridad)?v.prioridad:'media');
return [{json:{intencion:i,respuesta,intento,evento:a.evento,traceId:a.traceId,detalle,categoria:String(v.categoria||''),prioridad,critico,critico_corregido,resumen:String(v.resumen||''),inicio:v.inicio||'',fin:v.fin||''}}];

const j={...$json};
const fijo='No sé. Esa información no figura en el reglamento ni en la normativa del edificio. Si querés, derivo tu consulta a Administración.';
const steps=(()=>{let r;for(let i=0;i<3;i++){try{const a=$('[D1] Agente del consorcio').all(0,i);if(a.length)r=a[a.length-1].json}catch(e){break} }return r})().intermediateSteps||[];
const rag=Array.isArray(steps)?steps.filter(s=>s?.action?.tool==='RAG_reglamento'):[];
const info=['consulta','derivar'].includes(j.intencion);
const falta=/no dispongo|no tengo (esa )?informaci[oó]n|no cuento con|no figura|no encuentro|no est[aá] disponible|no (puedo|podemos) confirmar|no tengo (el|ese) (dato|importe|monto)/i;
const s=String(j.respuesta||'');
if((j.intencion==='consulta'&&!rag.length)||(info&&falta.test(s)&&!/^no sé\./i.test(s.trim()))){j.respuesta=fijo;return [{json:j}];}
if(rag.length&&!/^no sé\./i.test(s.trim())){
 const all=[];
 for(const step of rag){let v=step.observation;try{for(let i=0;i<3;i++){if(typeof v==='string'){v=JSON.parse(v);continue;}if(v&&typeof v==='object'&&!Array.isArray(v)&&'response' in v){v=v.response;continue;}break;}}catch{v=null;}if(Array.isArray(v))all.push(...v);}
 const roots=t=>[...new Set((String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().match(/[a-z0-9]+/g)||[]).filter(x=>x.length>=4).map(x=>x.slice(0,5)))];
 const wanted=roots(s);
 const candidates=all.filter(a=>typeof a?.fuente==='string'&&a.fuente.trim()&&typeof a.texto==='string').map((a,i)=>{const words=new Set(roots(a.texto));return {a,i,count:wanted.filter(x=>words.has(x)).length,reglamento:/reglamento[_\s-]*interno/i.test(a.fuente)}});
 candidates.sort((a,b)=>b.count-a.count||Number(b.reglamento)-Number(a.reglamento)||a.i-b.i);
 const fuente=candidates[0]?.a.fuente.trim()||'';
 if(!fuente||/^fuente no identificada/i.test(fuente)){if(info)j.respuesta=fijo;}
 else {
  j.fuente=fuente.replace(/\.md(?=\s*(?:·|$))/i,'').replace(/_/g,' ');
  const secciones=all.map(a=>typeof a?.fuente==='string'?a.fuente.split('·').slice(1).join('·').trim():'').filter(Boolean);
  const yaCita=/\.md\s*·/i.test(s)||secciones.some(title=>s.toLocaleLowerCase('es').includes(title.toLocaleLowerCase('es')));
  if(yaCita)j.respuesta=s.replace(/\.md\b/gi,'').replace(/_/g,' ');
  else if(!$('[A2] Validar entrada').first().json.modo_voz&&!/fuente\s*:/i.test(s))j.respuesta=s.trimEnd()+'\nFuente: '+fuente.replace(/\.md(?=\s*(?:·|$))/i,'').replace(/_/g,' ');
 }
}
return [{json:j}];
